531  static bool parse_headers(struct lwan_request_parser_helper *helper,
   532                            char *buffer,
   533                            char *buffer_end)
   534  {
   535      char **header_start = helper->header_start;
   536      char *p;
   537      size_t n_headers = 0;
   538      bool ret = false;
   539
   540      for (p = buffer + 1; n_headers < N_HEADER_START && buffer_end > p;) {
   541          char *next_chr = p;
   542          char *next_hdr = memchr(next_chr, '\r', (size_t)(buffer_end - p));
   543
   544          if (!next_hdr)
   545              goto process;
   546
   547          if (buffer_end - next_chr == sizeof("\r\n") - 1)
   548              goto process;
   549
   550          header_start[n_headers++] = next_chr;
   551          header_start[n_headers++] = next_hdr;
   552
   553          p = next_hdr + 2;
   554      }
   555
   556      goto out; /* Header array isn't large enough */
   557
   558  process:
   559      ret = true;
   560
   561      for (size_t i = 0; i < n_headers; i += 2) {
   562          char *end = header_start[i + 1];
   563
   564          p = header_start[i];
   565
   566          STRING_SWITCH_L(p) {
   567          case MULTICHAR_CONSTANT_L('A','c','c','e'):
   568              p += HEADER_LENGTH("Accept");
   569
   570              STRING_SWITCH_L(p) {
   571              case MULTICHAR_CONSTANT_L('-','E','n','c'):
   572                  helper->accept_encoding = HEADER("-Encoding");
   573                  break;
   574              }
   575              break;
   576          case MULTICHAR_CONSTANT_L('A','u','t','h'):
   577              helper->authorization = HEADER("Authorization");
   578              break;
   579          case MULTICHAR_CONSTANT_L('C','o','n','n'):
   580              helper->connection = HEADER("Connection");
   581              break;
   582          case MULTICHAR_CONSTANT_L('C','o','n','t'):
   583              p += HEADER_LENGTH("Content");
   584
   585              STRING_SWITCH_L(p) {
   586              case MULTICHAR_CONSTANT_L('-','T','y','p'):
   587                  helper->content_type = HEADER("-Type");
   588                  break;
   589              case MULTICHAR_CONSTANT_L('-','L','e','n'):
   590                  helper->content_length = HEADER("-Length");
   591                  break;
   592              }
   593              break;
   594          case MULTICHAR_CONSTANT_L('C','o','o','k'):
   595              helper->cookie = HEADER("Cookie");
   596              break;
   597          case MULTICHAR_CONSTANT_L('I','f','-','M'):
   598              helper->if_modified_since.raw = HEADER("If-Modified-Since");
   599              break;
   600          case MULTICHAR_CONSTANT_L('R','a','n','g'):
   601              helper->range.raw = HEADER("Range");
   602              break;
   603          }
   604      }
   605
   606  out:
   607      helper->next_request = buffer_end;
   608      helper->n_header_start = n_headers;
   609      return ret;
   610  }
